  constructor() {
    this.service.list().subscribe((list) => this.clients.set(list));
    this.loadBalances();
  }

  protected balanceOf(clientId: number): ClientBalance {
    return this.balances().get(clientId) ?? { clientId, balance: '0', overdue: '0', credit: '0' };
  }

  // Fetches what every client owes again, after a payment or other change to an invoice.
  protected loadBalances(): void {
    this.invoiceService
      .balances()
      .subscribe((list) => this.balances.set(new Map(list.map((b) => [b.clientId, b]))));
  }

  protected add(): void {
    const name = this.form.controls.name.value.trim();
    const email = this.form.controls.email.value.trim();
    const terms = this.form.controls.terms.value;
    const termsDays = terms === null || (terms as unknown) === '' ? null : Number(terms);
    const discount = this.form.controls.discountPct.value;
    const discountPct = discount === null || (discount as unknown) === '' ? null : Number(discount);
    const retention = this.form.controls.retentionPct.value;
    const retentionPct = retention === null || (retention as unknown) === '' ? null : Number(retention);
    const withholding = this.form.controls.withholdingPct.value;
    const withholdingPct = withholding === null || (withholding as unknown) === '' ? null : Number(withholding);
    const minimum = this.form.controls.minimumCharge.value;
    const minimumCharge = minimum === null || (minimum as unknown) === '' ? null : Number(minimum);
    const rateDiscount = this.form.controls.rateDiscountPct.value;
    const rateDiscountPct = rateDiscount === null || (rateDiscount as unknown) === '' ? null : Number(rateDiscount);
    const grace = this.form.controls.graceDays.value;
    const graceDays = grace === null || (grace as unknown) === '' ? null : Number(grace);
    const interest = this.form.controls.interestRate.value;
    const interestRate = interest === null || (interest as unknown) === '' ? null : Number(interest);
    const region = this.form.controls.region.value.trim();
    const taxNumber = this.form.controls.taxNumber.value.replace(/ /g, '');
    const taxExempt = this.form.controls.taxExempt.value;
    const pricesIncludeTax = this.form.controls.pricesIncludeTax.value;
    const currency = this.form.controls.currency.value;
    const early = this.form.controls.earlyPct.value;
    const earlyPayPct = early === null || (early as unknown) === '' ? null : Number(early);
    const earlyDays = this.form.controls.earlyDays.value;
    const earlyPayDays = earlyDays === null || (earlyDays as unknown) === '' ? null : Number(earlyDays);
    this.form.setValue({
      name,
      email,
      terms: termsDays,
      discountPct,
      retentionPct,
      withholdingPct,
      minimumCharge,
      rateDiscountPct,
      graceDays,
      interestRate,
      region,
      taxNumber,
      earlyPct: earlyPayPct,
      earlyDays: earlyPayDays,
      taxExempt,
      pricesIncludeTax,
      currency,
    });
    const problem = this.problemWith(
      name,
      email,
      termsDays,
      discountPct,
      retentionPct,
      withholdingPct,
      minimumCharge,
      rateDiscountPct,
      graceDays,
      interestRate,
      earlyPayPct,
      earlyPayDays,
      taxNumber,
    );
    if (problem) {
      this.form.markAllAsTouched();
      this.error.set(problem);
      return;
    }
    this.saving.set(true);
    this.error.set('');
    const client = {
      name,
      email,
      termsDays,
      discountPct: discountPct ?? 0,
      taxExempt,
      pricesIncludeTax,
      currency,
      earlyPayPct: earlyPayPct ?? 0,
      earlyPayDays,
      retentionPct: retentionPct ?? 0,
      withholdingPct: withholdingPct ?? 0,
      minimumCharge,
      rateDiscountPct: rateDiscountPct ?? 0,
      graceDays: graceDays ?? STANDARD_GRACE_DAYS,
      interestRate,
      region: region || null,
      taxNumber: taxNumber || null,
    };
    this.service.add(client).subscribe({
      next: (created) => {
        this.clients.update((list) => [...list, created].sort(byName));
        this.form.reset();
        this.saving.set(false);
      },
      error: (e: HttpErrorResponse) => {
        const detail: unknown = e.error?.detail;
        this.error.set(
          typeof detail === 'string' && detail ? detail : 'The client could not be added.',
        );
import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { Observable } from 'rxjs';
import { Currency } from '../invoices/invoice-format';

export interface Client {
  id: number;
  name: string;
  email: string;
  // Payment terms in days; null means due at the end of the month after issue.
  termsDays: number | null;
  // The standard percentage discount new invoices for the client start with; 0 is none.
  discountPct: number;
  // Whether the client is tax exempt (a charity, say): its invoices charge no tax on any line.
  taxExempt: boolean;
  // Whether the client is quoted prices that include tax: the tax is taken out of its invoice amounts.
  pricesIncludeTax: boolean;
  // The currency the client is billed in: everything on its invoices is in it.
  currency: Currency;
  // An early-payment discount: the percentage of the amount before tax (0 is none) taken off an invoice
  // paid off within earlyPayDays of its issue date (null when there is none).
  earlyPayPct: number;
  earlyPayDays: number | null;
  // The standard retention percentage (0 to 20) new invoices for the client start with; 0 is none.
  retentionPct: number;
  // The percentage (0 to 100) of each invoice's amount before tax the client withholds for its tax
  // office; 0 is none. The client never pays it.
  withholdingPct: number;
  // The client's own minimum charge, in its currency (no conversion), charged on its invoices instead
  // of the workspace's; null for the workspace's, 0 for never charged a minimum.
  minimumCharge: number | null;
  // The percentage (0 to 100) taken off every price the client's lines take from its rate card or the
  // price list, each band's price included; 0 is none. A price typed on a line is not reduced.
  rateDiscountPct: number;
  // Days (0 to 30, a week as standard) past its due date an invoice or instalment is given before it
  // is overdue and earns late interest.
  graceDays: number;
  // The client's own annual late-interest rate (0 to 30 percent) charged instead of the workspace's;
  // null for the workspace's, 0 for never charged late interest.
  interestRate: number | null;

